	m.EFSkipLastIP = types.BoolValue(getBool(obj, "EFSkipLastIP"))
	m.EFSkipMailGateway = stringSetValue(ctx, getStringSlice(obj, "EFSkipMailGateway"))
	m.EFTestMode = types.BoolValue(getBool(obj, "EFTestMode"))
